<script setup>
    import { onMounted, ref ,inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Custom Table' });
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

     const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const showMessage = inject('showMessage')
    const showError = inject('showError')
    const formatNumber = inject('formatNumber')
    const formatDate = inject('formatDate')
    const printlabourList = inject('printlabourList')
    const tableShimmer = inject('tableShimmer');
    const loading_spinner = ref(false);
    const columns = ref(['Sno', 'name','type','phone_no','rate', 'debt','currently_at','actions']);
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 , 100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['id', 'service_name'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const company_id = ref(6)

    const addlabour = ref(false)    
    const labourType = ref('')
    const labourTypes = ref([])
    const getLabourTypes = async () => {
        loading_spinner.value = true;
        try { 
            const response = await axiosInstance.get(`labour-types`);
            labourTypes.value = response.data
        } catch (error) {
            console.log(error)
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };

    const projects = ref([])
     const getProjects = async () => {
        loading_spinner.value = true;
        try { 
            const response = await axiosInstance.get(`projects`);
            projects.value = response.data
        } catch (error) {
            console.log(error)
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };

    const labourList = ref([])
  const getLabours = async () => {
        loading_spinner.value = true;
        try{
        const response = await axiosInstance.get(`labours?company_id=${company_id.value}`)
        labourList.value = response.data.map((item,index)=>({
         ...item,
         Sno : index + 1,
         name : item.name.toUpperCase(),
         rate : formatNumber(item.labour_type.rate),
         type : item.labour_type.name,
         debt : formatNumber(0),
         currently_at : item.project.short_name
        }))
        }catch(error){
            console.log(error)
            showError(error.message)
        }finally{
            loading_spinner.value = false;
        }
    };

    

    const name = ref('')
    const project = ref('')
    const rgisterLabour = async() => {
      loading_spinner.value = true
        const payload = {
            name: name.value,
            company_id: company_id.value,
            project_id: project.value.id,
            labour_type_id : labourType.value.id
        }
        try {
            const response = await axiosInstance.post('labours', payload);
            showMessage('Labour Registered');
            addlabour.value = !addlabour.value;
            await getLabours(); 
            
            name.value = '';
            project.value = '';
            labourType.value = '';
        } catch (error) {
            showError(error.message);
            console.log(error);
        }
    };

